    opp=3-me
    gid,groups=G.all_groups(board)
    tl={s:len(groups[gid[s]][1]) for s in range(81) if board[s]}
    Co={R:prop(board,me,seeds(board,me,'p3'),R) for R in (3,4)}
    Cx={R:prop(board,opp,seeds(board,opp,'par2'),R) for R in (3,4,5)}
    for p in range(81):
