        own=[q for q in G.NB[p] if board[q]==me]
        oppq=[q for q in G.NB[p] if board[q]==opp]
        tesc=any(tl[q]==1 for q in own)
        ne=sum(1 for n in G.NB[p] if board[n]==0)
