        for R in (3,4,5):
            dcap=any(len(Cx[R][q])<=1 for q in oppq)
            res[('cap',R,'fp')]+=dcap and not tcap
        for R in (3,4):
            C=Co[R]
            other=set()
            for q in own: other|=C[q]
