            if abs(A[6][i,U(('U0',6,s))]-u0)>1e-3: err('U0',(i,s,A[6][i,U(('U0',6,s))],u0))
            eye=1.0 if all(board[n]==1 for n in G.NB[s]) else 0.0
            if abs(A[6][i,U(('eye',6,s))]-eye)>1e-4: err('eye',(i,s))
